mapper.update:
UPDATE file_cleanup_task
SET attempts = attempts + 1,
    next_attempt_at =
        TIMESTAMPADD(SECOND, #{retryDelaySeconds}, CURRENT_TIMESTAMP(6)),
    last_error = #{lastError}
WHERE id = #{taskId}

mapper.select:
SELECT
    EXISTS (
        SELECT 1
        FROM post_file pf
        WHERE pf.storage_key = #{targetKey}
            OR pf.thumbnail_key = #{targetKey}
    )
OR EXISTS (
    SELECT 1
    FROM file_cleanup_task fct
    WHERE fct.target_key = #{targetKey}
)
